export function getCollection(slug: string): Collection | undefined {
  return collections.find((c) => c.slug === slug);
}

export function getProduct(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug);
}

export function getProductsByCollection(slug: string): Product[] {
  return products.filter((p) => p.collection === slug);
}

export function getProductsByTopLevel(top: TopLevel): Product[] {
  return products.filter((p) => p.topLevel === top);
}

export function getCollectionsByTopLevel(top: TopLevel): Collection[] {
  return collections.filter((c) => c.topLevel === top);
}
